/* Voz Livre · Didática de cada aula
   Exemplos, passo a passo para o professor, materiais simples e dicas separadas para crianças e adultos.
   Campos de cada aula:
     m  = materiais (objetos simples e baratos)
     ex = exemplo ou imagem para explicar o conceito
     p  = passo a passo da aula em sala
     c  = como ensinar crianças
     a  = como ensinar adultos (e jovens)
     e  = erros comuns e como corrigir: [erro, correção]
     al = o que o aluno faz em casa com o material: {kid, adult}
*/
window.VL_DIDA={
/* ================= NÍVEL 1 ================= */
posture:{
 m:'Espelho, um livro leve, parede lisa e uma cadeira firme.',
 ex:'"O corpo é o violão da voz": se o violão estiver torto ou amassado, a corda até vibra, mas o som sai feio. Mostre uma garrafa PET em pé e outra amassada: o ar passa melhor na que está em pé.',
 p:['Peça para todos se encostarem na parede: calcanhares, bumbum, costas e nuca encostados. Depois deem um passo à frente mantendo essa sensação.','Pés na largura dos ombros, joelhos destravados. Faça a turma "balançar como árvore" e parar no centro.','Ombros: subir até as orelhas, segurar 3 segundos e soltar de uma vez. Repita 3 vezes.','Coloque um livro leve na cabeça de cada um e peça para andar e falar "bom dia" sem o livro cair. Isso alinha a cabeça sem esticar o queixo.','Termine sentados: pés no chão, sentados na ponta da cadeira, costas longe do encosto.'],
 c:'Transforme em brincadeira: "estátua de cantor". Quando você para a música, todos congelam na postura certa. Quem estiver com ombro levantado ou joelho travado "derrete" e faz de novo, sem eliminar ninguém.',
 a:'Explique o porquê: costela livre deixa o ar entrar, cabeça alinhada deixa a laringe livre. Adultos aceitam melhor a correção quando entendem a função. Use o espelho de lado para cada um ver o próprio perfil.',
 e:[['Queixo para cima nas notas agudas','Peça para olhar um ponto na altura dos olhos e imaginar um fio puxando o topo da cabeça, não o queixo.'],['Joelhos travados','Peça uma "mini dobradinha" nos joelhos. Joelho travado cansa e trava a respiração.']],
 al:{kid:'Antes de cantar, encoste na parede da sua casa e faça a "estátua de cantor". Depois tente andar com um livro na cabeça!',adult:'Antes de treinar, faça 30 segundos na parede e confira o perfil no espelho: orelha, ombro e quadril na mesma linha.'}},
breath:{
 m:'Um livro (ou bichinho de pelúcia para as crianças), tapete ou colchonete, uma folha de papel e um lenço de papel.',
 ex:'"Encher o pneu de baixo": o ar enche primeiro a parte de baixo, como água num copo, que enche do fundo para cima. Os ombros não são o lugar do ar.',
 p:['Deitados de barriga para cima, com um livro (ou pelúcia) sobre a barriga. Ao inspirar pelo nariz, o livro sobe; ao soltar o ar, ele desce.','Agora em pé, mão na barriga e outra no peito: só a mão de baixo se mexe.','Mãos na lateral das costelas: sentir as costelas abrirem "como um guarda-chuva".','Faça o ciclo do app: inspira 4, segura 2, solta 6 em "sss".','Teste do lenço: segure um lenço de papel encostado na parede só com o sopro. Quem segura mais tempo controla melhor o ar.'],
 c:'Use a pelúcia na barriga: "vamos fazer o ursinho passear de elevador". Diga "cheira a flor" para inspirar e "esvazia o balão" para soltar em "sss", como uma cobrinha.',
 a:'Explique que o diafragma desce na inspiração e empurra as vísceras, por isso a barriga sai. Deitado é a posição em que todo mundo respira certo naturalmente: é a referência do corpo para depois repetir em pé.',
 e:[['Ombros sobem ao inspirar','Volte para deitado com o livro, ou peça para inspirar com as mãos na cintura e os polegares nas costas.'],['Soltar o ar todo de uma vez','Use o lenço na parede ou a tira de papel: ela deve tremer de leve e sem parar, não voar e cair.']],
 al:{kid:'Deite na cama com seu bichinho de pelúcia na barriga e faça ele subir e descer 5 vezes. Depois faça a cobrinha "sss" até o ar acabar.',adult:'Todos os dias, 2 minutos deitado com um livro na barriga, e depois o desafio do lenço na parede. Anote quantos segundos você segura o lenço.'}},
health:{
 m:'Uma garrafinha de água por aluno, um copo e duas mãos limpas (para a demonstração das "pregas").',
 ex:'Bata as palmas das mãos com força por 30 segundos: elas ficam vermelhas e ardendo. É o que acontece com as pregas vocais quando gritamos ou pigarreamos. Agora bata de leve: dá para fazer por muito tempo.',
 p:['Comece com a demonstração das palmas para mostrar o atrito das pregas.','Mostre a garrafinha: "a água que você bebe hoje hidrata a voz de amanhã". Combine pequenos goles durante a aula toda.','Ensine a trocar o pigarro por engolir saliva ou por uma tossidinha leve com a boca fechada.','Leia os sinais de alerta (rouquidão por mais de 15 dias, dor, falha) e diga que nesse caso é hora de procurar médico ou fonoaudiólogo.','Feche com o quiz do app em voz alta.'],
 c:'Crie o "time da voz saudável": cada criança ganha uma tarefa (beber água, não gritar no recreio, dormir cedo). Na próxima aula, cada um conta se cumpriu e ganha um adesivo.',
 a:'Pergunte sobre a rotina de cada um: quem fala muito no trabalho, quem dá aula, quem fuma ou toma muito café. Adapte os conselhos à vida real e explique que cantar cansado é o maior risco.',
 e:[['Achar que gargarejo ou bala de menta "limpa a voz"','Explique que nada que se engole toca nas pregas vocais. O que hidrata é a água bebida com antecedência e o vapor.'],['Gritar no culto ou no esporte e cantar logo depois','Combine o "dia seguinte leve": depois de um dia de muito uso, só aquecimento suave.']],
 al:{kid:'Encha uma garrafinha de manhã e tente terminar até a noite. Desafio: passar o dia todo sem gritar!',adult:'Anote por uma semana: quantos copos de água, horas de sono e momentos em que falou alto. Traga para conversar na próxima aula.'}},
warm:{
 m:'Um canudo, um copo com água pela metade e um cata-vento de papel (opcional, para as crianças).',
 ex:'"Ninguém corre a maratona sem alongar": o aquecimento é o alongamento da voz. Mostre um elástico frio, que estica pouco, e depois de esticá-lo devagar algumas vezes, que estica mais.',
 p:['Massagem: bochechas e maxilar com as pontas dos dedos, boca levemente aberta.','Vibração de lábios ("brrr", a moto): se os lábios não vibrarem, apoie um dedo em cada bochecha.','Canudo no copo d\'água: fazer bolhas com som de "uuu", subindo e descendo como sirene. As bolhas devem ser contínuas e calmas.','Humming ("mmm", a abelhinha), sentindo cócegas nos lábios.','Sirene em "u" do grave para o agudo e de volta, em volume baixo.'],
 c:'Conte uma historinha: "a moto ligou (brrr), passou pelo rio (bolhas no canudo), uma abelha apareceu (mmm) e chegou a ambulância (sirene)". As crianças adoram repetir a história a cada aula.',
 a:'Explique que o canudo e a vibração de lábios equilibram a pressão do ar e protegem as pregas: é o mesmo exercício que fonoaudiólogos passam. Aquecimento de 5 minutos já faz diferença.',
 e:[['Bolhas muito fortes no copo','Peça bolhas "de aquário", pequenas e contínuas. Bolha forte é ar demais.'],['Sirene alta e forçada no agudo','A sirene é baixinha. Se a voz falhar no meio, ótimo: é só continuar leve.']],
 al:{kid:'Peça um canudo e um copo d\'água para alguém de casa e faça as bolhas cantando "uuu" por 1 minuto, bem devagar.',adult:'Deixe um canudo na bolsa ou no carro. Antes de cantar no culto, 2 minutos de canudo (no copo ou no ar) já aquecem.'}},
ear_hl:{
 m:'Teclado, violão ou o próprio app, e dois cartões: um com seta para cima (agudo) e outro com seta para baixo (grave). Uma escada ou degrau também ajuda.',
 ex:'Agudo é o som do passarinho e do apito; grave é o som do trovão e do caminhão. Mostre no teclado: para a direita fica mais fino (agudo), para a esquerda mais grosso (grave).',
 p:['Toque um som bem grave e um bem agudo e pergunte qual é qual, com exemplos do dia a dia.','Distribua os cartões de seta. Toque duas notas: todos levantam a seta da segunda nota (subiu ou desceu).','Diminua a distância entre as notas aos poucos: de muito longe para bem perto.','Inclua o "igual": as duas notas iguais, mãos na cabeça.','Cada aluno faz no app e conta a pontuação.'],
 c:'Jogo do corpo: som agudo, fica na ponta dos pés com os braços para cima; som grave, agacha; igual, fica parado. Use a escada: um degrau para cima no agudo, um para baixo no grave.',
 a:'Muitos adultos confundem agudo com forte e grave com fraco. Toque a mesma nota forte e fraca e pergunte se mudou a altura. Separar volume de altura é o ponto central desta aula.',
 e:[['Confundir alto (volume) com agudo','Toque o mesmo som forte e fraco: "mudou o volume, não a altura".'],['Errar quando as notas estão muito perto','Volte para notas mais distantes e aproxime de novo, devagar.']],
 al:{kid:'Brinque com alguém de casa: a pessoa faz uma voz fina ou grossa e você mostra com o corpo (ponta do pé ou agachado).',adult:'Faça o exercício do app de manhã e à noite por 3 dias. Ao ouvir louvores, tente perceber se cada frase sobe ou desce.'}},
first:{
 m:'Teclado ou o app para dar a nota, um espelho e uma tira de papel ou fita para representar a "linha" da nota.',
 ex:'Cantar afinado é como "encaixar a voz" na nota, como uma chave entrando na fechadura. Primeiro a gente escuta, depois imagina, e só depois canta.',
 p:['Toque a nota e peça para todos só escutarem, de olhos fechados.','Peça para "cantar por dentro" (imaginar a nota) por 2 segundos.','Todos cantam "uuu" juntos, bem leve.','Use a mão como régua: se a voz está baixa, você sobe a mão devagar; o aluno acompanha a mão até encaixar.','Mostre no app o balão ou a linha: abaixo da estrela é para subir, acima é para descer.'],
 c:'Use a mão como "elevador": a criança canta e segue a sua mão subindo ou descendo até chegar no "andar" certo. Comemore cada acerto com o Davi do app.',
 a:'Quem nunca cantou muitas vezes acha que é "desafinado". Explique que afinação é ouvido treinado e coordenação, não dom. Comece na nota mais confortável do aluno, nunca na sua.',
 e:[['Cantar em outra oitava (muito grave ou muito agudo)','Cante a nota na região do aluno, ou use o tom calculado pelo teste de voz.'],['Começar a cantar antes de ouvir','Combine o gesto: mão fechada = só ouvir, mão aberta = pode cantar.']],
 al:{kid:'Faça a aula no app e tente levar o balão até a estrela 3 vezes seguidas. Use a mão para mostrar se a voz precisa subir ou descer.',adult:'Faça a aula todos os dias até ganhar a estrela. Antes de cantar, imagine a nota por um segundo: esse hábito vale para sempre.'}},
sustain:{
 m:'Relógio ou cronômetro do celular, tira de papel (ou cata-vento) e um caderno para anotar os recordes.',
 ex:'O ar é como o dinheiro do mês: quem gasta tudo no primeiro dia fica sem nada no fim. Na nota longa, a gente "gasta" o ar devagar e no mesmo ritmo.',
 p:['Revise a respiração com a mão na barriga.','Segure uma tira de papel na frente da boca e cante "uuu": a tira deve tremer de leve e por igual, sem voar.','Todos sustentam juntos enquanto você marca o tempo.','Anote o tempo de cada aluno no caderno, para comparar com ele mesmo nas próximas aulas.','Repita com o objetivo de ganhar 1 ou 2 segundos, sem forçar no fim.'],
 c:'Use o cata-vento: "vamos fazer o cata-vento girar devagar o máximo de tempo". Crie a "tabela de campeões" na parede, onde cada criança compete só com o próprio recorde.',
 a:'O objetivo é regularidade e não só tempo. Peça para ouvirem se o volume cai no fim. Uma nota de 10 segundos estável vale mais que 20 segundos tremendo.',
 e:[['Volume cai e a voz treme no fim','Pare um pouco antes do ar acabar. Treinar no limite cria tensão.'],['Inspirar muito, com os ombros, para "ter mais ar"','Mais ar nos ombros não ajuda. Volte para a respiração baixa, sem exagero.']],
 al:{kid:'Peça ajuda para marcar o tempo no relógio e anote seu recorde de "uuu". Tente bater o recorde na semana!',adult:'Sustente "uuu" 3 vezes por dia e anote o melhor tempo. Use a tira de papel para conferir se o ar sai constante.'}},
voicehow:{
 m:'Uma bexiga (balão de festa), um elástico de dinheiro e um copo de plástico ou garrafa.',
 ex:'A bexiga é a melhor demonstração: encha, estique o bico e solte o ar devagar. Ela "canta"! O ar é o pulmão, o bico que vibra são as pregas vocais. Esticando mais o bico, o som fica mais agudo.',
 p:['Faça a demonstração da bexiga: ar (pulmão), vibração (pregas), e mostre que esticar mais deixa o som mais agudo.','Elástico esticado entre os dedos: puxe e solte. O som é fraco. Agora encoste no copo de plástico: o som fica mais forte. É a ressonância (boca, nariz, garganta).','Peça para todos colocarem a mão na garganta e falarem "aaa": sentir a vibração. Depois "sss": não vibra.','Mostre a articulação: a mesma vibração vira "a", "i" ou "u" só mudando a boca.','Faça o quiz do app.'],
 c:'Deixe as crianças ouvirem a bexiga cantando (você segura). Diga que dentro do pescoço tem "duas cortininhas" que fazem isso quando a gente fala e canta, e por isso precisamos cuidar delas.',
 a:'Ligue cada parte a um problema: falta de ar (fonte), voz rouca ou soprosa (pregas), voz abafada ou sem brilho (ressonância), letra que não se entende (articulação). Assim o aluno sabe o que treinar.',
 e:[['Achar que a voz "sai do peito" ou "da barriga"','A voz nasce nas pregas vocais. A barriga controla o ar e o peito e a cabeça vibram por ressonância.'],['Achar que voz bonita é questão de garganta forte','Mostre com a bexiga: quem faz o som é a vibração livre, não a força.']],
 al:{kid:'Peça para um adulto encher uma bexiga e fazer ela "cantar". Depois coloque a mão no pescoço e fale "aaa" e "sss": em qual tem vibração?',adult:'Fale uma frase com a mão no pescoço, depois no peito e depois no nariz. Perceba onde vibra mais em cada vogal.'}},
exam1:{
 m:'Celular com o app e fone de ouvido, um lugar silencioso.',
 ex:'A prova é como o "ensaio geral": mostra o que já está firme e o que precisa de mais treino, não é para reprovar ninguém.',
 p:['Faça um aquecimento curto antes (moto, abelhinha e sirene).','Explique as partes: ouvir agudo e grave, e cantar uma nota afinada.','Deixe o aluno fazer sozinho, sem ajuda, para ser um retrato real.','Ouça a gravação no painel e comente um ponto forte e um ponto para melhorar.'],
 c:'Chame de "desafio da medalha" e não de prova. Fique perto, incentive, e se a criança ficar nervosa, faça uma pausa com a respiração do balão.',
 a:'Diga claramente que pode refazer quantas vezes quiser. Muitos adultos travam por medo de errar; tirar esse peso melhora o resultado.',
 e:[['Fazer a prova sem aquecer','Sempre 2 minutos de aquecimento antes.'],['Ambiente barulhento atrapalhando o microfone','Escolha um cômodo silencioso e use fone.']],
 al:{kid:'Faça o aquecimento com o Davi e depois o desafio da medalha. Se não der, tente de novo amanhã!',adult:'Faça a prova num momento tranquilo, depois de aquecer, e envie a gravação para o professor.'}},

/* ================= NÍVEL 2 ================= */
vowels:{
 m:'Espelho e uma rolha ou o dedo indicador (para medir a abertura da boca).',
 ex:'As vogais são "roupas" diferentes para a mesma nota: troca a roupa, mas a pessoa é a mesma. A nota não pode mudar quando a boca muda.',
 p:['Na frente do espelho, mostre a forma de cada vogal: A (dois dedos de abertura), É (sorriso aberto), I (sorriso, dentes aparecendo), Ó (boca redonda), U (biquinho).','Cante as vogais faladas, sem nota, exagerando a forma.','Agora todos numa nota só: A, É, I, Ó, U, com pausa entre elas.','Ouça se alguma vogal desafina (o I costuma subir e o U costuma cair).','Faça no app e veja se a linha fica no mesmo lugar nas cinco vogais.'],
 c:'Faça "caretas de vogal" no espelho: A de jacaré, É de sorriso, I de rato, Ó de surpresa, U de beijinho. Depois a mesma careta cantando.',
 a:'Explique que a vogal muda a ressonância e às vezes puxa a afinação. Peça para o queixo ficar solto e a língua encostada nos dentes de baixo em todas as vogais.',
 e:[['O "I" fica estridente e sobe','Abra um pouco mais a boca no I, como se pensasse num "ê".'],['Queixo travado na mesma posição','Use o espelho: o queixo desce um pouco no A e no Ó.']],
 al:{kid:'Na frente do espelho, faça as caretas das vogais e depois cante cada uma numa nota só.',adult:'Cante as cinco vogais numa nota confortável na frente do espelho, cuidando para o queixo ficar solto.'}},
scale3:{
 m:'Fita crepe para desenhar uma escadinha no chão (ou três livros empilhados como degraus), e o teclado ou o app.',
 ex:'A escala é uma escada: cada nota é um degrau. A voz sobe um degrau de cada vez, sem pular nenhum e sem tropeçar.',
 p:['Desenhe três degraus no chão com fita crepe (Dó, Ré, Mi).','Toque as três notas e cante você primeiro.','A turma canta enquanto pisa em cada degrau, um passo por nota.','Cante com a mão subindo em degraus na frente do corpo.','Faça no app e mostre a linha subindo em escadinha.'],
 c:'Andar na escada de fita crepe é perfeito para crianças: o corpo aprende o "subir". Peça para uma criança pisar e as outras cantarem a nota em que ela está.',
 a:'Use os números (1, 2, 3) e a mão em degraus. Explique que os degraus desta escada têm o mesmo tamanho (um tom). Peça para ouvirem a sequência toda antes de cantar.',
 e:[['Subir demais no 3º degrau','Cante 1-2-3 bem devagar e volte sempre ao 1 para conferir.'],['Escorregar entre as notas (glissando)','Use o "lu": a língua marca o começo de cada degrau.']],
 al:{kid:'Use três livros ou três almofadas como degraus e cante "lu, lu, lu" subindo com o pé em cada um.',adult:'Faça a aula no app e depois cante 1-2-3 com a mão marcando os degraus, sem o app, para ver se se mantém afinado.'}},
scale5:{
 m:'Escada de fita crepe com 5 degraus (o degrau entre Mi e Fá desenhado mais curto), teclado ou app.',
 ex:'Na escada da música, um dos degraus é mais baixinho: do Mi para o Fá. Quem não presta atenção sobe demais e "tropeça".',
 p:['Amplie a escada do chão para 5 degraus, com o 3º para o 4º degrau visivelmente menor.','Mostre no teclado que entre Mi e Fá não há tecla preta: é o meio tom.','Cante 3-4-3-4 algumas vezes para sentir o meio tom.','Cante a escala inteira pisando nos degraus.','Faça no app e confira o 4º grau.'],
 c:'Diga que o degrau do Fá é o "degrau do anão", bem pequenininho. As crianças passam a cantar esse degrau com cuidado.',
 a:'Explique tom e semitom no teclado (tecla preta no meio ou não). É o ponto onde quase todo iniciante desafina: treine 3-4-3 isolado antes da escala inteira.',
 e:[['Fá muito alto (passa do meio tom)','Treine 3-4-3 bem devagar, imaginando um passo curto.'],['Perder o fôlego no 5º grau','Respire antes e mantenha o ar até o fim, sem pressa.']],
 al:{kid:'Monte sua escada de 5 almofadas, com uma bem pertinho da outra no meio, e cante subindo.',adult:'Treine só 3-4-3-4-3 cinco vezes antes de fazer a escala inteira no app.'}},
theory_scale:{
 m:'Teclado (pode ser de brinquedo ou um app de piano no celular) e sete copos ou garrafas com níveis diferentes de água (opcional).',
 ex:'Garrafas com água em níveis diferentes, batidas com uma colher, formam uma escala: quanto menos água, mais agudo. Mostra que cada nota é um "tamanho" de som.',
 p:['Mostre as sete notas no teclado e que depois do Si volta o Dó (a oitava).','Explique tom (pula uma tecla) e semitom (tecla vizinha), apontando no teclado.','Monte a escala maior: tom, tom, semitom, tom, tom, tom, semitom.','Se tiver as garrafas, deixe os alunos tocarem a escala.','Faça o quiz em voz alta.'],
 c:'Ensine a "família das notas" que mora numa rua de 7 casas e, depois do Si, começa outra rua igual. Use as garrafas com água colorida.',
 a:'Ligue a teoria à prática: "o meio tom do Mi para o Fá que você treinou na escala de 5 notas está aqui". Ofereça um app de piano para eles explorarem em casa.',
 e:[['Achar que toda tecla preta fica no meio de duas brancas','Mostre que entre Mi-Fá e Si-Dó não tem tecla preta.'],['Decorar sem entender','Peça para cada um montar uma escala começando em outra nota, contando tons e semitons.']],
 al:{kid:'Encha copos com água em alturas diferentes (com a ajuda de um adulto) e bata de leve com uma colher para ouvir as notas.',adult:'Baixe um app de piano gratuito e toque a escala de Dó maior, contando tom e semitom em voz alta.'}},
updown:{
 m:'Escada de fita crepe, uma bolinha (de papel ou de tênis) e o app.',
 ex:'Descer a escada também exige atenção: quem desce correndo tropeça. Na música, a voz que desce "caindo" acaba desafinando para baixo.',
 p:['Suba e desça a escada do chão cantando 1-2-3-4-5-4-3-2-1.','Mostre a bolinha: na subida ela sobe na mão; na descida, desça a mão devagar, "segurando" a bolinha, sem deixá-la cair.','Peça para pensarem a descida "por cima" da nota, mantendo o apoio do ar.','Grave a turma no celular e ouçam se a última nota chegou no lugar.','Faça no app.'],
 c:'Faça a "descida do elevador lento": o elevador desce andar por andar e para certinho no térreo. Quem chegar abaixo do térreo foi "para o porão".',
 a:'Explique que na descida o corpo relaxa o apoio e a voz cai. Peça para manter a mesma energia da subida até a última nota. Toque o 1º grau no fim para comparar.',
 e:[['Última nota abaixo da inicial','Toque a nota inicial no fim. Peça para "pensar para cima" ao descer.'],['Correr na descida','Marque o tempo com a mão e cante igual na ida e na volta.']],
 al:{kid:'Suba e desça sua escada de almofadas cantando, bem devagar na descida, como um elevador lento.',adult:'Grave-se cantando a escala e compare a última nota com a primeira no app.'}},
ear_int:{
 m:'Teclado ou app, e cartões com o início de músicas conhecidas para cada intervalo.',
 ex:'Cada intervalo ganha uma "música-gancho" para lembrar: a 2ª é o "-ra-béns" de "Parabéns pra você"; a 3ª são as duas primeiras notas do "Pulinho de nota" (1-3); a 5ª é o pulo entre o primeiro e o segundo "brilha" de "Brilha, brilha, estrelinha"; a oitava é a mesma nota mais fina, como um homem e uma criança cantando juntos. O melhor gancho, porém, é um hino que a turma já canta.',
 p:['Toque cada intervalo e associe a uma música conhecida da turma.','Toque um intervalo e peça para a turma cantar a música-gancho correspondente.','Faça um "jogo de adivinhar" em grupos: cada acerto vale ponto.','Cada um faz no app e anota a porcentagem.'],
 c:'Use músicas infantis como ganchos ("Brilha, brilha, estrelinha" para a 5ª). Faça a brincadeira de "qual é a música?": a criança ouve o pulinho e descobre.',
 a:'Monte com a turma a lista de ganchos usando hinos e louvores que eles cantam na igreja. O gancho pessoal é muito mais fácil de lembrar.',
 e:[['Confundir 3ª com 5ª','Cante as notas do meio: 1-2-3 é perto; 1-2-3-4-5 é mais longe.'],['Tentar acertar sem cantar','Peça para cantar baixinho as duas notas antes de responder.']],
 al:{kid:'Cante "Brilha, brilha, estrelinha" e perceba o pulo grande do "bri-lha" para o "es-tre". Depois faça o jogo do app.',adult:'Escreva 1 música-gancho para cada intervalo (2ª, 3ª, 5ª e oitava) e use até acertar 80% no app.'}},
leaps:{
 m:'Três objetos em alturas diferentes (chão, cadeira e mesa) ou três copos empilhados, e o app.',
 ex:'Pular de nota é como o sapo pulando de pedra em pedra no rio: antes de pular, ele olha onde vai cair. Na música, a gente "ouve por dentro" antes de pular.',
 p:['Cante 1-2-3-4-5 e depois só 1-3-5, mostrando que pulamos degraus.','Coloque um objeto no chão (1), na cadeira (3) e na mesa (5). Aponte enquanto cantam.','Antes de cada salto, faça uma pausa curta para "imaginar a nota".','Cante 1-3-5-3-1 juntos, depois em pequenos grupos.','Faça no app.'],
 c:'Faça o "pulo do sapo" de verdade: marque três lugares no chão e a criança pula de um para outro cantando. Se cantar certo, o sapo não cai na água.',
 a:'Explique que é o arpejo do acorde maior, a base de muitos louvores. Mostre no violão ou teclado o acorde e as três notas. Peça para cantar as notas do meio "por dentro" se errar o salto.',
 e:[['Errar a 5ª (cantar baixo demais)','Cante 1-2-3-4-5 baixinho por dentro e só então solte o 5.'],['Fazer um escorregão entre as notas','Use "lu" com um início limpo em cada nota.']],
 al:{kid:'Marque três lugares no chão e faça o pulo do sapo cantando "lu" em cada pulo.',adult:'Cante 1-3-5-3-1 imaginando a nota antes de cada salto. Se errar, cante a escala por dentro e tente de novo.'}},
long:{
 m:'Tira de papel, uma fita esticada na parede (a "linha da nota") e o app.',
 ex:'A nota longa é como andar numa corda bamba: o pé (a voz) fica em cima da linha, sem balançar para os lados. O ar é o equilíbrio.',
 p:['Revise a respiração e o "sss" contínuo.','Mostre a fita na parede: a voz tem que "andar" em cima dela.','Todos sustentam a nota juntos, enquanto você passa o dedo na fita.','Use a tira de papel na frente da boca para ver se o ar sai constante.','Faça no app e observe se a linha fica reta.'],
 c:'Diga que a voz é um carrinho andando em cima de uma linha no chão. Desenhe a linha com fita crepe e a criança "dirige" o carrinho com o dedo enquanto canta.',
 a:'Junte as três coisas: respiração, apoio e ouvido. Peça para ouvirem a nota de referência por dentro durante toda a sustentação, não só no começo.',
 e:[['Nota começa certa e cai no fim','Mantenha o apoio até o final e pare antes do ar acabar.'],['Voz tremendo','Reduza o volume e verifique tensão nos ombros e no queixo.']],
 al:{kid:'Cante a nota comprida passando o dedo numa linha desenhada no papel, sem sair da linha.',adult:'Sustente a nota no app olhando a linha do gráfico, 3 vezes por dia, sem forçar no final.'}},
follow1:{
 m:'Metrônomo (app gratuito) ou palmas, e o app.',
 ex:'É como pular corda: não adianta pular bem se for na hora errada. A nota tem que chegar na hora em que a corda passa.',
 p:['Bata palmas no pulso, todos juntos.','Cante a escala falando os números no tempo das palmas.','Agora cante em "lá" no tempo, com a mão marcando o pulso.','Mostre no app as notas passando pela linha e cantem juntos.','Faça grupos: um grupo bate palma e o outro canta.'],
 c:'Use a ideia do "trenzinho": cada vagão (nota) passa pela estação (linha) na hora certa. Ande em fila pela sala cantando, um passo por tempo.',
 a:'Explique que agora a nota é a porcentagem do tempo em que esteve afinado. Use um metrônomo bem lento no início e suba devagar.',
 e:[['Atrasar nas notas mais longas','Conte "1, 2" em voz baixa nas notas de dois tempos.'],['Esperar ver a nota para cantar','Ouça uma vez antes e cante pensando na próxima nota.']],
 al:{kid:'Ande pela casa como um trenzinho, um passo por nota, cantando a escala em "lá".',adult:'Treine com o metrônomo a 60 e depois a 80, cantando a escala no tempo, antes de fazer no app.'}},
support:{
 m:'Uma vela apagada ou tira de papel, faixa elástica (ou cinto/lenço amarrado na cintura) e uma bola leve.',
 ex:'O apoio é o "freio de mão" do ar: o ar não sai de uma vez, sai controlado pelos músculos da barriga e das costelas. Como uma mangueira com o dedo na ponta controlando o jato.',
 p:['Amarre um lenço ou faixa elástica na cintura do aluno. Ao inspirar, ele empurra a faixa para fora; ao fazer "sss", tenta manter a faixa esticada o máximo de tempo.','"Sss" contínuo com a tira de papel: ela treme de leve e sem parar.','Pulsos "ts-ts-ts": a barriga dá um pulinho para dentro em cada "ts".','Staccato "ha-ha-ha", como uma risada de Papai Noel, mão na barriga.','"Vvv" sustentado, sentindo os lábios vibrarem e a barriga trabalhar devagar.'],
 c:'Para o "ha-ha-ha", faça a risada do Papai Noel ou do gigante. Para os pulsos, "o cachorrinho cansado" (cuidado para não ficar tonto: poucos e com pausa). Para o "sss", a cobrinha que não pode parar.',
 a:'Explique que apoio não é endurecer a barriga, é manter as costelas abertas e liberar o ar aos poucos. Use a faixa elástica para dar a sensação física, que adultos entendem rápido.',
 e:[['Endurecer a barriga como uma tábua','Peça para empurrar a faixa de leve, com elasticidade, não com força.'],['Ficar tonto nos pulsos','Faça séries curtas com pausas. Tontura é sinal de ar demais.']],
 al:{kid:'Faça a risada do Papai Noel ("ha-ha-ha") 5 vezes com a mão na barriga e a cobrinha "sss" segurando o papel.',adult:'Com um cinto ou lenço na cintura, faça 3 séries de "sss" mantendo as costelas abertas. Depois 10 pulsos "ts".'}},
diction:{
 m:'Uma rolha limpa ou uma caneta grossa (para segurar entre os dentes), espelho e uma Bíblia.',
 ex:'Se a letra não se entende, a mensagem não chega. É como uma carta com a letra borrada. No louvor, a congregação precisa entender cada palavra para cantar junto.',
 p:['Aquecimento de lábios e língua: estalar a língua, "brrr" e caretas.','Exercício da rolha: segurar a rolha (ou caneta) entre os dentes da frente e ler um versículo tentando ser entendido. Depois tirar a rolha e ler de novo: a fala fica muito mais clara.','Pa-ta-ka acelerando aos poucos.','Trava-língua, começando devagar.','Leitura do Salmo 23:1 como se cantasse, abrindo bem a boca.'],
 c:'Faça o campeonato de trava-línguas: devagar primeiro, depois mais rápido. Para os pequenos, use "lá-lé-li-ló-lu" com a mão imitando a língua.',
 a:'O exercício da rolha é muito eficaz: força lábios e língua a trabalharem mais. Faça 1 minuto e depois leia a letra de um hino. A diferença convence qualquer adulto.',
 e:[['Consoantes finais sumindo ("Senhô", "amô")','Peça para exagerar o R e o S finais e depois diminuir mantendo a clareza.'],['Mandíbula presa, boca pouco aberta','Use o espelho e peça "dois dedos" de abertura nas vogais abertas.']],
 al:{kid:'Escolha um trava-língua e treine até falar 3 vezes sem errar. Mostre para alguém de casa!',adult:'Leia um salmo em voz alta com a rolha (ou caneta) entre os dentes por 1 minuto e depois sem ela. Faça isso antes de cantar.'}},
dyn:{
 m:'Um elástico (ou faixa elástica) e uma bola, ou o controle de volume da TV como exemplo.',
 ex:'A dinâmica é o "botão de volume" da voz. Estique um elástico devagar (crescendo) e solte devagar (diminuendo). Forte não é gritar: é mais ar com apoio.',
 p:['Mostre o elástico: pouco esticado é suave, bem esticado é forte, e volta devagar.','Cante uma nota em quatro volumes: normal, suave, forte e suave, esticando o elástico junto.','Observe pescoço e ombros no forte: não pode haver veia saltando.','No suave, peça a mão na barriga: o ar continua ativo.','Faça no app, que mede o volume em relação à voz normal de cada um.'],
 c:'"Forte e fraquinho": o leão (forte, mas sem gritar) e o ratinho (suave). Quando você levanta a mão, cantam forte; quando abaixa, suave. Lembre: cantar baixinho é como contar um segredo para Deus.',
 a:'Mostre como a dinâmica muda a mensagem: cante "Santo, santo, santo" suave e depois forte. Adultos entendem rápido que dinâmica é interpretação, não só técnica.',
 e:[['Desafinar no suave (cai) ou no forte (sobe)','Treine a mesma nota afinada nos dois volumes, devagar.'],['Forte vindo da garganta','Volte para o "ha-ha-ha" do apoio e peça o forte "da barriga".']],
 al:{kid:'Cante a mesma nota como um leão e como um ratinho, e peça para alguém de casa adivinhar qual é qual.',adult:'Estique um elástico enquanto canta uma nota, crescendo e diminuindo. Repita a aula no app 2 ou 3 vezes na semana.'}},
song1:{
 m:'A letra impressa em letras grandes (ou no quadro), o app e o teclado ou violão.',
 ex:'Aprender um hino é como montar um quebra-cabeça: primeiro peça por peça (nota por nota), depois a figura inteira (a frase no ritmo).',
 p:['Leia a letra juntos, como uma oração, e converse sobre o que ela diz.','Fale a letra no ritmo, batendo palmas.','Toque a melodia e cante você primeiro.','A turma repete em pedaços pequenos (2 ou 3 sílabas).','Faça no app, sílaba por sílaba.'],
 c:'Faça um gesto para cada palavra importante ("Cristo" = mão no coração, "Bíblia" = mãos abertas como livro). Os gestos ajudam a decorar e a entender a mensagem.',
 a:'Mostre que as notas repetidas precisam de articulação clara. Peça para cada aluno marcar na letra onde vai respirar antes de cantar.',
 e:[['Sílabas embolando nas notas repetidas','Cante devagar, com uma pausinha entre as notas repetidas.'],['Cantar a letra e esquecer a afinação','Cante primeiro em "lu", depois com a letra.']],
 al:{kid:'Cante o louvor com os gestos para alguém da sua família.',adult:'Fale a letra no ritmo, depois cante em "lu" e só então com a letra, no app.'}},
follow2:{
 m:'Letra impressa, metrônomo ou palmas e o app com fone.',
 ex:'Agora as peças do quebra-cabeça se juntam: a frase toda, sem parar, como um trem que não para em cada estação.',
 p:['Revise a frase nota por nota.','Bata o pulso e fale a letra no ritmo.','Cante com você ao teclado, sem parar mesmo se errar.','Mostre no app como as notas passam na tela.','Cada aluno canta sozinho uma vez e a turma aplaude o esforço.'],
 c:'Combine a regra do "não para": se errar, continua cantando, como no culto. Use palmas para manter o ritmo.',
 a:'Ensine a ideia de "errar e seguir": no culto não dá para parar. Mostre as colcheias ("me a-") que dão o balanço da frase.',
 e:[['Parar ao errar uma nota','Combine continuar e só corrigir depois.'],['Correr nas colcheias','Fale "ti-ti" nas colcheias e "ta" nas semínimas.']],
 al:{kid:'Cante o louvor junto com o app, sem parar, mesmo se errar uma notinha.',adult:'Com fone, cante junto no app até chegar a 60 ou mais. Marque o pulso com o pé.'}},
song2:{
 m:'Letra impressa com setas desenhadas mostrando se a melodia sobe ou desce, e o app.',
 ex:'Esta melodia é como uma montanha-russa: sobe, desce e tem curvas. Desenhe a "montanha" da melodia no quadro em cima da letra.',
 p:['Desenhe no quadro uma linha que sobe e desce acompanhando a melodia.','Cante passando o dedo na linha.','Destaque os saltos ("Pre-ci-o") e treine-os separados.','Marque onde respirar: entre as duas frases.','Faça no app, nota por nota.'],
 c:'Desenhe a montanha-russa da melodia e deixe a criança "andar" com o dedo enquanto canta. Diga que respirar entre as frases é a "parada para pegar ar".',
 a:'Converse sobre a história do hino (Amazing Grace), muito conhecido. Mostre os saltos de 4ª e as notas de passagem, e peça para marcar a respiração na letra.',
 e:[['Errar o salto inicial "Pre-ci"','Cante só as duas primeiras notas várias vezes, imaginando antes.'],['Respirar no meio de uma palavra','Marque com uma vírgula na letra onde respirar.']],
 al:{kid:'Desenhe a montanha-russa da melodia num papel e cante passando o dedo nela.',adult:'Imprima a letra, marque as respirações a lápis e faça a aula no app.'}},
follow3:{
 m:'Metrônomo, um lenço ou fita para "desenhar" o compasso no ar e o app.',
 ex:'Compasso de 3 é como uma valsa: UM-dois-três, UM-dois-três. Balance o corpo de um lado para o outro no "um".',
 p:['Balance a turma no compasso de 3: forte no 1.','Cante a melodia em "lu" balançando.','Com um lenço na mão, desenhe um triângulo no ar (o gesto do regente em 3).','Mostre as notas longas no fim das frases: segurar até a próxima chegar.','Faça no app com fone.'],
 c:'Dance a valsa: cada criança com um lenço, girando no "um". As notas longas são o "giro comprido".',
 a:'Mostre o gesto do regente em 3. Explique que a nota longa precisa de apoio até o fim, sem cortar antes do tempo.',
 e:[['Cortar as notas longas antes do tempo','Conte os tempos em voz baixa e só respire no fim.'],['Sentir em 2 em vez de 3','Bata o 1 no joelho e o 2 e 3 nas mãos.']],
 al:{kid:'Pegue um lenço e dance a valsa cantando o hino, girando no "um".',adult:'Cante com o metrônomo marcando 3 tempos e depois faça no app até 60 ou mais.'}},
song3:{
 m:'Um barbante ou fita comprida e o app.',
 ex:'Legato é cantar "ligado", como um barbante que não se corta. Cada nota é um nó no barbante, mas o barbante é um só.',
 p:['Conte um pouco da história: a Doxologia é cantada há mais de 400 anos.','Estique o barbante entre duas pessoas: a frase é um fio contínuo.','Cante em "lu" passando a mão ao longo do barbante, sem parar o som.','Agora com a letra, mantendo o legato.','Faça no app, nota por nota.'],
 c:'Use o barbante: as crianças cantam enquanto o barbante "passa" pelas mãos delas sem cair. Se o som parar, o barbante cai.',
 a:'Explique legato como ligar as vogais e deixar as consoantes rápidas. É um hino ótimo para treinar porque as notas andam por graus conjuntos.',
 e:[['Cortar o som entre as notas','Cante em "u" contínuo, depois volte à letra.'],['Empurrar cada nota (acento em todas)','Peça uma frase "deslizando", com uma única direção.']],
 al:{kid:'Passe um barbante pelas mãos enquanto canta, sem deixar o som parar.',adult:'Cante a frase em "u" contínuo e depois com a letra, buscando o mesmo legato.'}},
follow4:{
 m:'Letra impressa com as quatro frases numeradas e o app.',
 ex:'Quatro frases, quatro respirações, como quatro degraus de uma escadaria: em cada patamar a gente descansa e respira.',
 p:['Numere as quatro frases na letra.','Combine que a respiração é na nota longa do fim de cada frase.','Cante a Doxologia inteira, no tempo.','Faça a turma em dois grupos alternando as frases.','Faça no app.'],
 c:'Faça duas equipes: uma canta as frases 1 e 3, a outra as frases 2 e 4. No fim, todos juntos.',
 a:'Mostre que é o fim do Nível 2 em louvores. Peça para cantar pensando no sentido de cada frase (Pai, Filho e Espírito).',
 e:[['Respirar no meio das frases','Marque as respirações e cante mais devagar no começo.'],['Acelerar no fim','Mantenha o pulso com o pé do começo ao fim.']],
 al:{kid:'Cante a Doxologia inteira com alguém da sua casa, cada um uma frase.',adult:'Cante a Doxologia inteira com o app e depois sozinho, sem acompanhamento, conferindo o tom no fim.'}},
teb_seq:{
 m:'Letra impressa e o app.',
 ex:'Louvores atuais repetem muito as frases. Aprender a primeira frase bem resolve metade da música.',
 p:['Leia a letra e destaque o que se repete.','Cante você a primeira frase e a turma repete.','Cante em "lu", depois com a letra.','Faça no app, nota por nota.'],
 c:'Faça uma brincadeira de "eco": você canta, eles repetem como um eco, primeiro alto e depois baixinho.',
 a:'Mostre a estrutura (frase A, frase B) e como a repetição facilita decorar.',
 e:[['Errar as notas longas','Segure as notas longas contando os tempos.'],['Correr nas sílabas rápidas','Fale a letra no ritmo antes de cantar.']],
 al:{kid:'Brinque de eco com alguém da sua casa: a pessoa canta e você repete.',adult:'Cante nota por nota no app e depois a frase inteira sem ajuda.'}},
teb:{
 m:'Metrônomo e o app.',
 ex:'As notas longas são as "paradas de ônibus" da música: em "bom", "Senhor", "fim" e "mim" a gente descansa e respira.',
 p:['Marque na letra as notas longas onde se respira.','Cante com palmas no pulso.','Cante com o app, com fone.','Peça para um aluno cantar e os outros marcarem o pulso.'],
 c:'Nas notas longas, as crianças abrem os braços como um avião. Ajuda a segurar até o fim.',
 a:'Mostre que o estilo atual pede leveza e ritmo firme. Respire nas notas longas, nunca no meio da frase.',
 e:[['Cortar as notas longas','Abra os braços e segure até o fim.'],['Atrasar depois de respirar','Respire rápido e no tempo.']],
 al:{kid:'Cante o refrão abrindo os braços nas notas compridas.',adult:'Com fone, cante no app até 60 ou mais.'}},
exam2:{
 m:'App, fone e lugar silencioso.',
 ex:'A prova do Nível 2 é como a "formatura do básico": mostra que o aluno já tem ouvido, afinação e ritmo para os louvores.',
 p:['Aquecimento completo antes.','Revise rapidamente intervalos e a escala.','Deixe o aluno fazer a prova sozinho.','Ouça a gravação e comente.'],
 c:'Prepare uma pequena comemoração (aplausos, adesivo) para quem completar, com ou sem nota alta.',
 a:'Lembre que pode repetir. Comente a gravação com um ponto forte e um ponto a melhorar.',
 e:[['Nervosismo atrapalhando o ritmo','Faça a respiração 4-2-6 antes.'],['Esquecer de aquecer','Aquecimento é parte da prova.']],
 al:{kid:'Aqueça com o Davi e faça o desafio da medalha do Nível 2!',adult:'Faça a prova depois de aquecer e envie a gravação.'}},

/* ================= NÍVEL 3 ================= */
theory_reg:{
 m:'Mão no peito e mão na cabeça (o próprio corpo), uma escada de 2 andares desenhada no quadro e, se tiver, um carro de brinquedo para mostrar a "troca de marcha".',
 ex:'Os registros são as "marchas" do carro: a 1ª marcha (voz de peito) tem força para o grave, a 4ª marcha (voz de cabeça) é leve para o agudo. A passagem é a troca de marcha: se for brusca, o carro dá um tranco (a voz quebra).',
 p:['Peça mão no peito e fale "ô" grave, grosso: sentir vibrar no peito (voz de peito).','Mão no topo da cabeça e faça um "u" agudo como uma coruja ou um fantasma: vibra mais na cabeça (voz de cabeça).','Faça uma sirene do grave ao agudo e peça para notarem onde a voz "quebra": é a passagem.','Explique a voz mista: uma mistura que permite subir sem quebrar e sem gritar.','Faça o quiz do app.'],
 c:'"Voz de urso" (peito) e "voz de passarinho" (cabeça). O urso e o passarinho são amigos e querem cantar juntos: essa é a voz mista.',
 a:'Adultos, principalmente homens, costumam evitar a voz de cabeça por achá-la "feminina". Explique que todo cantor profissional usa e que é ela que salva os agudos sem grito.',
 e:[['Levar a voz de peito até o agudo, gritando','Mostre que o grito é peito puxado demais. Treine a voz de cabeça leve antes.'],['Achar que a quebra é defeito','A quebra é normal no início: é exatamente o que vamos treinar.']],
 al:{kid:'Fale com voz de urso (mão no peito) e voz de passarinho (mão na cabeça). Depois faça uma sirene bem baixinho, do urso até o passarinho.',adult:'Faça uma sirene leve do grave ao agudo e anote em que nota a sua voz quebra. Essa é a sua passagem.'}},
chest:{
 m:'Mão no peito, espelho e uma garrafa PET vazia (para sentir a vibração).',
 ex:'Encoste a garrafa no peito e fale "mã": a garrafa vibra. A voz de peito é a voz de conversa animada, cheia e firme, como chamar alguém do outro lado da rua sem gritar.',
 p:['Fale "mã, mã, mã" como uma conversa animada, mão no peito.','Encoste uma garrafa no peito para sentir a vibração.','Cante 5-4-3-2-1 em "mã" na região média-grave.','Observe o espelho: boca aberta, queixo solto, pescoço sem veias saltadas.','Faça no app.'],
 c:'Use "voz de urso": a criança fala como um urso grandão (sem gritar), com a mão no peito sentindo "tremer".',
 a:'Peça volume de fala e não de grito. O descendente 5-4-3-2-1 é mais fácil porque leva a voz para onde o peito é natural.',
 e:[['Empurrar a voz, ficando rouco','Diminua o volume: conversa animada, não discussão.'],['Abaixar o queixo para engrossar a voz','Use o espelho e mantenha a cabeça alinhada.']],
 al:{kid:'Fale e cante "mã" com voz de urso, com a mão no peito sentindo tremer.',adult:'Cante 5-4-3-2-1 em "mã" com a mão no peito, em volume de conversa.'}},
head:{
 m:'Mão no topo da cabeça, um lenço de papel e um apito ou som de coruja como exemplo.',
 ex:'A voz de cabeça é leve como a coruja fazendo "uuu" ou um fantasma de desenho. Ela não precisa de força: precisa de leveza.',
 p:['Imite uma coruja ou um fantasma: "uuu" agudo e leve.','Mão no topo da cabeça para sentir a vibração subir.','Cante a sequência aguda em "u" com pouco volume.','Segure um lenço de papel na frente da boca: ele deve mexer bem pouco (pouco ar, voz leve).','Faça no app.'],
 c:'Faça a "voz de fantasminha" ou "corujinha". As crianças fazem com facilidade; elogie a leveza.',
 a:'Homens: falsete e voz de cabeça podem parecer estranhos no começo. Explique que é treino de coordenação e que esse som leve vai se fortalecer com o tempo.',
 e:[['Voz soprosa demais','Use o "u" mais focado, como um "uu" de surpresa.'],['Puxar a voz de peito para o agudo','Comece pelo topo e desça, sempre leve.']],
 al:{kid:'Faça a voz de corujinha bem baixinho: "uuu" fininho, com a mão na cabeça.',adult:'Faça a aula com volume baixo e pare se sentir aperto. A leveza é o objetivo.'}},
sovt:{
 m:'Um canudo por aluno (de preferência fino), um copo ou garrafa com água pela metade.',
 ex:'O canudo na água cria uma "almofada de ar" que protege as pregas vocais. É como andar na piscina: a água segura o corpo e você não cai.',
 p:['Canudo no ar: cante "uuu" pelo canudo numa sirene leve.','Canudo no copo d\'água (2 a 5 cm de profundidade): bolhas contínuas enquanto canta sirenes e escalas.','Vibração de lábios em oitava.','"Ng" (como no fim de "ping") em sirene, sentindo o som no nariz.','"Gui" em saltos, mantendo a sensação do canudo.'],
 c:'Chame de "fazer bolhas cantando". Peça bolhas pequenas e contínuas, como um aquário. Fique atento para não beberem a água do copo de outro colega.',
 a:'Explique que é o exercício mais usado por fonoaudiólogos: reduz o atrito e equilibra a passagem. Mais fundo na água = mais resistência. Ótimo também para recuperar a voz cansada.',
 e:[['Bochechas estufadas','Segure as bochechas com os dedos ou use um canudo mais grosso.'],['Bolhas fortes e descontroladas','Menos ar: bolhas de aquário, contínuas.']],
 al:{kid:'Com um canudo e um copo d\'água, faça bolhas cantando "uuu" subindo e descendo, como uma sirene.',adult:'Leve um canudo com você. Faça 3 minutos de canudo na água antes de treinar e depois de um dia de muita fala.'}},
passage:{
 m:'Canudo, um elástico e o app.',
 ex:'Passar pela passagem é como subir uma rampa e não uma escada com degrau alto: o caminho é suave, sem tranco.',
 p:['Aqueça com canudo em sirene, atravessando a passagem.','Cante a escala de oitava no canudo.','Agora em "u", diminuindo o volume conforme sobe.','Estique um elástico conforme sobe e solte devagar ao descer: o elástico mostra a "suavidade".','Faça no app.'],
 c:'Use o carro de brinquedo subindo uma rampa feita com um livro: o carro sobe devagar, sem pular.',
 a:'A dica de ouro: diminuir o volume conforme sobe. Quem sobe aumentando o volume quebra a voz.',
 e:[['Quebra na passagem','Volte ao canudo e faça a mesma escala, depois em "u" mais suave.'],['Aumentar o volume no agudo','Pense "subir e ficar menor".']],
 al:{kid:'Faça a sirene no canudo subindo e descendo bem suave, sem a voz pular.',adult:'Faça a escala no canudo e logo depois em "u", diminuindo o volume na subida.'}},
range_up:{
 m:'Uma bola leve (ou bolinha de papel) e o app.',
 ex:'O agudo é como jogar uma bola para o alto: se você joga com força demais, perde o controle. Jogue leve e ela sobe e volta para a sua mão.',
 p:['Jogue uma bola leve para cima a cada arpejo: a voz acompanha a bola subindo e descendo.','Cante 1-3-5-8-5-3-1 em "iá".','Repita um tom acima.','Peça leveza no topo, sem esticar o pescoço.','Faça no app.'],
 c:'Cada criança joga uma bolinha de papel para cima enquanto canta o arpejo. A voz "sobe com a bola".',
 a:'A extensão cresce com repetição e leveza, não com força. Pare quando sentir aperto: tensão hoje é perda de extensão amanhã.',
 e:[['Queixo para cima no topo','Olhe para a frente e pense o agudo "para trás e para cima" da cabeça.'],['Forçar a nota mais alta','Pare um tom abaixo do limite.']],
 al:{kid:'Jogue uma bolinha de papel para cima e cante o arpejo acompanhando a bola.',adult:'Faça a aula leve, 2 a 3 vezes por semana, e anote a nota mais alta confortável.'}},
range_low:{
 m:'Espelho e um livro (para equilibrar na cabeça, evitando abaixar o queixo).',
 ex:'O grave é como descer uma escada carregando uma bandeja: a postura fica reta, não curvada. Quem abaixa o queixo aperta a garganta.',
 p:['Coloque um livro leve na cabeça para lembrar a postura.','Desça em "ô", mantendo o livro equilibrado.','Observe no espelho: queixo paralelo ao chão.','Mantenha o apoio do ar no grave.','Faça no app.'],
 c:'"Voz de urso dormindo": um "ô" bem grave, mas sem engolir a voz. O livro não pode cair.',
 a:'O grave precisa de ar, não de pressão. Muitos homens empurram a laringe para baixo: peça leveza e postura.',
 e:[['Abaixar o queixo para engrossar a voz','Use o livro na cabeça.'],['Voz sumindo no grave','Mais ar e menos pressão, e não desça além do confortável.']],
 al:{kid:'Com um livro na cabeça, cante "ô" bem grave como um urso dormindo, sem deixar o livro cair.',adult:'Cante os graves com um livro na cabeça e confira o queixo no espelho.'}},
octave:{
 m:'Uma escada de verdade (2 ou mais degraus) ou uma cadeira, e o app.',
 ex:'O salto de oitava é como subir um andar de elevador: você não sobe degrau por degrau, mas precisa saber exatamente em que andar vai chegar.',
 p:['Cante 1-8-1 devagar, mostrando a oitava no teclado (mesma nota, mais aguda).','Antes do salto, cante a oitava "por dentro".','Gesto: a mão sobe num arco suave, como jogar algo por cima de um muro.','Mantenha o mesmo ar no salto.','Faça no app.'],
 c:'Use a imagem do canguru: um pulo grande, mas que cai certinho. A criança faz o gesto do arco com a mão.',
 a:'Explique que a nota de cima pede voz de cabeça (leve). Quem pula com a voz de peito empurrada grita ou erra.',
 e:[['Chegar baixo no 8','Imagine a nota antes e faça o arco com a mão.'],['Grito no salto','Mais leveza e menos volume na nota de cima.']],
 al:{kid:'Faça o arco com a mão enquanto canta o pulo de canguru.',adult:'Cante 1-8-1 imaginando a nota de cima antes de cada salto.'}},
theory_rhythm:{
 m:'Palmas, um copo plástico por aluno (para batidas), e uma pizza ou bolo desenhado no quadro (para mostrar figuras).',
 ex:'As figuras rítmicas são pedaços de pizza: a semibreve é a pizza inteira (4 tempos), a mínima é meia pizza (2), a semínima é um quarto (1) e a colcheia é um oitavo (meio tempo).',
 p:['Bata o pulso com o pé, todos juntos.','Mostre o compasso de 4: forte no 1.','Desenhe a pizza e as figuras.','Bata ritmos simples com o copo na mesa.','Faça o quiz do app.'],
 c:'Jogo dos copos: cada criança bate o copo na mesa no ritmo. Use palavras: "pão" (1 tempo), "ba-ta" (2 colcheias).',
 a:'Use a pizza e a contagem "1 e 2 e". Adultos aprendem rápido com a fala rítmica "ta" e "ti-ti".',
 e:[['Acelerar sem perceber','Use o metrônomo bem lento.'],['Confundir figura e pausa','Desenhe as duas lado a lado.']],
 al:{kid:'Bata palmas falando "pão, pão, ba-ta, pão".',adult:'Com um metrônomo, bata palmas em semínimas e colcheias, contando "1 e 2 e".'}},
tap1:{
 m:'Metrônomo e um copo ou caneta para bater na mesa.',
 ex:'O metrônomo é o "relógio" da música. Tocar no tempo é como encaixar os passos numa marcha.',
 p:['Ligue o metrônomo e bata o pulso.','Leia o ritmo falando "ta" e "ti-ti".','Bata o ritmo na mesa com uma caneta.','Faça no app, tocando no ataque de cada nota.'],
 c:'Marcha de soldadinho: a criança marcha no pulso e bate palmas no ritmo.',
 a:'Explique que tocar no ataque (o começo da nota) é o que conta. Comece em 60 bpm.',
 e:[['Tocar adiantado','Pense "esperar o clique".'],['Perder a contagem nas notas longas','Conte em voz baixa.']],
 al:{kid:'Marche pela casa e bata palmas no ritmo.',adult:'Bata os ritmos com uma caneta no tempo do metrônomo e depois faça no app até 70 pontos.'}},
theory_read:{
 m:'Cinco barbantes ou fitas no chão (a pauta), tampinhas de garrafa ou moedas (as notas) e uma cifra impressa de um hino.',
 ex:'A pauta é um prédio de cinco andares: quanto mais alto a nota mora, mais agudo é o som. A clave de sol diz que o Sol mora na 2ª linha.',
 p:['Monte uma pauta no chão com cinco barbantes.','Coloque tampinhas nas linhas e espaços e diga os nomes.','Mostre a clave de sol e o Sol na 2ª linha.','Mostre a cifra: letras (C, D, E...) e onde cada acorde muda na letra do hino.','Faça o quiz do app.'],
 c:'"Pauta gigante" no chão: a criança pula de linha em linha dizendo o nome das notas.',
 a:'Foque no útil para o cantor: saber se a melodia sobe ou desce, reconhecer o tom pela cifra e conversar com a banda.',
 e:[['Confundir linhas e espaços','Use cores diferentes para linhas e espaços.'],['Confundir A com Dó','Monte uma tabela: A=Lá, B=Si, C=Dó, D=Ré, E=Mi, F=Fá, G=Sol.']],
 al:{kid:'Desenhe uma pauta num papel e coloque feijões nas notas, dizendo os nomes.',adult:'Pegue a cifra de um hino que você canta e escreva o nome de cada acorde em português.'}},
staff1:{
 m:'Pauta desenhada no papel ou no quadro, cartões com notas (flashcards) e o app.',
 ex:'O Sol da 2ª linha é a "casa de referência": a partir dela você conta para cima e para baixo para achar as outras notas.',
 p:['Revise a referência do Sol.','Faça um "jogo rápido" com cartões: mostre e a turma responde.','Faça o mesmo com as cifras.','Cada um faz no app.'],
 c:'Jogo da memória com cartões de notas e cartões com o nome.',
 a:'Monte flashcards no celular ou papel e treine 5 minutos por dia.',
 e:[['Contar do zero toda vez','Decore 3 referências: Dó central, Sol da 2ª linha e Dó do 3º espaço.'],['Confundir as cifras','Use a tabela de letras até decorar.']],
 al:{kid:'Brinque de jogo da memória com cartões de notas que você mesmo desenhou.',adult:'Treine com flashcards 5 minutos por dia e faça a aula até 80%.'}},
song4:{
 m:'Letra impressa e o app.',
 ex:'Esta melodia caminha por graus conjuntos, como alguém subindo e descendo uma ladeira tranquila. No fim da frase, uma síncope dá um "tropeço" proposital.',
 p:['Leia a letra como oração.','Cante em "lu" com legato.','Treine a síncope do fim da frase separada.','Cante com a letra.','Faça no app, nota por nota.'],
 c:'Conte que a melodia é famosa no mundo inteiro (Hino à Alegria). Faça uma marcha alegre enquanto cantam.',
 a:'Explique a síncope e o legato. Mostre a melodia de Beethoven adaptada para o louvor.',
 e:[['Perder o legato na letra','Cante em "lu" e depois com a letra.'],['Errar a síncope','Fale o ritmo antes de cantar.']],
 al:{kid:'Cante o hino marchando pela casa.',adult:'Faça a aula nota por nota e depois cante sem ajuda.'}},
follow5:{
 m:'Metrônomo e o app.',
 ex:'A semínima pontuada seguida de colcheia é como um "passo longo e um curtinho", um pequeno pulo no fim da frase.',
 p:['Fale o ritmo "taaa-ti".','Cante a melodia em "lu" com palmas.','Cante com a letra e o app.','Peça para respirarem nas pausas de frase.'],
 c:'Faça o passo longo e o passo curto andando: "pé-grande, pé-pequeno".',
 a:'Mostre o ponto de aumento no papel e conte "1-2-e" na figura pontuada.',
 e:[['Transformar o pontuado em duas notas iguais','Fale "taaa-ti" antes de cantar.'],['Respirar no meio da frase','Marque as respirações.']],
 al:{kid:'Ande pela casa fazendo "pé-grande, pé-pequeno" enquanto canta.',adult:'Cante com o app até 60 ou mais, contando o pontuado.'}},
amv:{
 m:'Palmas, um chocalho (garrafa com arroz ou feijão) e o app.',
 ex:'Contratempo é entrar "no meio" do tempo, como pular corda entrando depois que a corda passou. Dá o balanço dos louvores atuais.',
 p:['Faça um chocalho com garrafa e arroz.','Bata o pulso com o pé e o contratempo com o chocalho.','Fale a letra no ritmo.','Cante com o app.'],
 c:'Faça chocalhos com garrafinhas e grãos. Todos tocam no contratempo enquanto você canta.',
 a:'Explique a síncope e o contratempo. Ouça o exemplo e sinta o balanço antes de cantar.',
 e:[['Entrar no tempo em vez do contratempo','Bata o pé no tempo e cante entre as batidas.'],['Ficar rígido','Balance o corpo de leve.']],
 al:{kid:'Faça um chocalho com garrafa e arroz e toque enquanto canta.',adult:'Ouça o exemplo várias vezes e cante batendo o pé no tempo.'}},
amr:{
 m:'Canudo (para aquecer o agudo) e o app.',
 ex:'O refrão é o "céu aberto" da música: sobe, abre e louva. Precisa de apoio, não de grito.',
 p:['Aqueça com canudo.','Cante os "aleluias" em "lu".','Cante com a letra, segurando o "ia".','Faça no app.'],
 c:'Os braços se abrem em cada "aleluia", como quem louva.',
 a:'Voz aberta com apoio, sem empurrar. Pense em voz mista no agudo.',
 e:[['Gritar no agudo','Menos volume, mais apoio.'],['Cortar o "ia"','Segure até o fim.']],
 al:{kid:'Cante o refrão abrindo os braços em cada "aleluia".',adult:'Aqueça com canudo e depois cante o refrão com o app.'}},
exam3:{
 m:'App, fone e lugar silencioso.',
 ex:'A prova do Intermediário confirma leitura, ritmo e um hino completo.',
 p:['Aqueça com canudo e sirenes.','Revise a leitura e o ritmo.','O aluno faz a prova sozinho.','Ouça a gravação e comente.'],
 c:'Celebre a conquista do nível com toda a turma.',
 a:'Lembre que pode repetir. Comente a gravação.',
 e:[['Pressa na leitura','Respire antes de cada parte.'],['Esquecer de aquecer','Aquecimento faz parte.']],
 al:{kid:'Aqueça e faça o desafio da medalha do Nível 3!',adult:'Faça a prova depois de aquecer e envie a gravação.'}},

/* ================= NÍVEL 4 ================= */
theory_vib:{
 m:'Uma régua de plástico presa na mesa (para mostrar oscilação) e uma corda ou fita.',
 ex:'Prenda uma régua na beirada da mesa e dê um toque: ela vibra sozinha, num ritmo natural. O vibrato é assim: não se fabrica, aparece quando a voz está livre.',
 p:['Mostre a régua vibrando sozinha.','Explique que o vibrato vem da liberdade e do apoio.','Ouça exemplos de vibrato natural e de vibrato forçado (tremido ou "de bode").','Converse sobre o uso no louvor: com equilíbrio.','Faça o quiz do app.'],
 c:'Para crianças, mostre a régua vibrando e diga que a voz também "dança" sozinha quando está feliz e solta. Não exija vibrato de crianças.',
 a:'Explique os vícios: mexer o queixo, a barriga ou a laringe para fabricar vibrato. Nota reta e afinada também é bonita.',
 e:[['Fabricar vibrato com o queixo','Use o espelho: o queixo fica parado.'],['Vibrato largo demais','Reduza o volume e a pressão.']],
 al:{kid:'Prenda uma régua na mesa e veja ela dançar sozinha. Assim é a voz livre!',adult:'Ouça cantores que você admira e perceba se o vibrato é suave ou exagerado.'}},
vib_prep:{
 m:'Espelho, canudo e uma bola de pilates ou travesseiro (opcional).',
 ex:'Para a régua vibrar, ela precisa estar solta. Para a voz vibrar, mandíbula, língua e pescoço precisam estar soltos.',
 p:['Solte a mandíbula com massagem e "bocejo".','Língua para fora e de volta, relaxando.','Pulsos de apoio leves.','Oscilação lenta entre duas notas.','Nota longa livre, olhando o espelho.'],
 c:'Faça o "boneco de pano": o corpo fica mole, depois canta uma nota leve.',
 a:'Use o espelho para observar o queixo. O objetivo é eliminar tensão, não produzir vibrato agora.',
 e:[['Queixo mexendo','Apoie um dedo no queixo.'],['Pescoço tenso','Gire os ombros e boceje antes.']],
 al:{kid:'Faça o boneco de pano e depois uma nota bem leve.',adult:'Faça a preparação todos os dias, 5 minutos, olhando o espelho.'}},
vib_osc:{
 m:'Espelho e o app.',
 ex:'A oscilação lenta é como balançar um balanço: primeiro devagar e depois mais rápido, mas sempre no mesmo ritmo.',
 p:['Alterne duas notas em "u", lento.','Acelere aos poucos.','Observe o queixo no espelho.','Faça no app.'],
 c:'Não é necessário para crianças pequenas. Se fizerem, chame de "balanço da voz".',
 a:'Quem move a nota é o ar e as pregas, não o queixo. Comece lento.',
 e:[['Queixo mexendo','Apoie um dedo no queixo.'],['Acelerar demais','Mantenha um ritmo regular.']],
 al:{kid:'Faça o balanço da voz bem devagar.',adult:'Faça a oscilação lenta olhando o espelho e acelere aos poucos.'}},
vibrato:{
 m:'Espelho e o app.',
 ex:'O vibrato natural aparece no fim de uma nota longa bem apoiada, como a régua que vibra sozinha depois do toque.',
 p:['Aqueça com canudo.','Cante uma nota longa em "a" com apoio.','Deixe o vibrato aparecer no fim.','Faça no app.'],
 c:'Não exija vibrato de crianças. Elogie a nota longa reta e afinada.',
 a:'Uma nota reta e afinada também avança. O vibrato vem com o tempo.',
 e:[['Forçar o vibrato','Reduza o volume e relaxe.'],['Vibrato largo','Menos pressão.']],
 al:{kid:'Cante uma nota comprida e bonita, reta e afinada.',adult:'Treine a preparação todos os dias e a aula de vibrato 2 vezes por semana.'}},
theory_agil:{
 m:'Metrônomo (app gratuito), uma bolinha de papel e um teclado de celular para comparar com "digitar".',
 ex:'Agilidade é como digitar no celular: quem digita devagar e certo acaba ficando rápido; quem tenta ser rápido de primeira escreve tudo errado. Na voz, primeiro a nota limpa, depois a velocidade.',
 p:['Cante um pequeno melisma (várias notas numa só sílaba) e pergunte quantas notas ouviram.','Explique a regra: precisão primeiro, velocidade depois.','Mostre o método do metrônomo: começar em 60, subir de 4 em 4 só quando sair limpo 3 vezes seguidas.','Mostre os erros comuns cantando: aspirar ("ha-ha-ha"), deslizar e mexer o queixo.','Faça o quiz do app.'],
 c:'"Formiguinha corredora": cada nota é um passinho leve e rápido. Formiga que pisa forte demais tropeça. Faça os passinhos com os dedos na mesa enquanto cantam.',
 a:'Adultos querem resultados rápidos. Mostre que meia velocidade limpa vale mais que velocidade cheia suja, e que o cérebro aprende o padrão devagar.',
 e:[['Treinar rápido demais desde o início','Metrônomo lento e só acelerar quando sair limpo 3 vezes.'],['"Ha-ha-ha" entre as notas','Ar contínuo, como se fosse uma nota longa que muda de altura.']],
 al:{kid:'Faça os passinhos da formiguinha com os dedos na mesa cantando "a-a-a-a-a".',adult:'Instale um metrônomo e anote, a cada treino, a velocidade em que o padrão saiu limpo.'}},
agil1:{
 m:'Metrônomo e uma bola pequena (de tênis ou de meia).',
 ex:'1-2-3-2-1 é um pulinho rápido para cima e de volta, como quicar uma bola: leve, sem segurar.',
 p:['Cante 1-2-3-2-1 lento, em "a", cada nota bem clara.','Com o metrônomo em 60, uma nota por clique; depois duas notas por clique (colcheias).','Quique a bola no chão no tempo: a voz acompanha a leveza da bola.','Passe para o padrão de 5 notas.','Faça no app.'],
 c:'Cada criança quica uma bola (ou finge) e canta uma nota a cada quique. Bola leve, voz leve.',
 a:'Peça o queixo parado (use o espelho) e o "a" sempre igual. Se uma nota cair, ouça de novo antes de repetir, nunca repita errado.',
 e:[['Notas deslizando (glissando)','Mais lento, e pense em cada nota como um ponto.'],['Voz pesada','Menos volume: agilidade pede leveza.']],
 al:{kid:'Quique uma bola cantando "a" em cada quique, subindo e descendo.',adult:'Treine no metrônomo 3 minutos por dia, subindo a velocidade só quando sair limpo.'}},
agil2:{
 m:'Metrônomo e uma fita ou barbante comprido.',
 ex:'A escala rápida é uma escada rolante: suave e contínua. Não é uma escada que você sobe pulando degraus.',
 p:['Cante a escala de 5 notas lenta, depois em colcheias.','Faça a escala de oitava em "a".','Passe a mão ao longo de um barbante esticado enquanto canta: o movimento é contínuo.','Diminua o peso no agudo e mantenha o ar na descida.','Faça no app.'],
 c:'Faça a escada rolante com a mão subindo e descendo, sem parar.',
 a:'O erro mais comum é pesar no topo e perder o ar na descida. Pense "leve em cima, apoio embaixo".',
 e:[['Peso no agudo','Menos volume na parte de cima da escala.'],['Afinação caindo na descida','Mantenha o apoio até a última nota.']],
 al:{kid:'Faça a escada rolante com a mão enquanto canta a escala.',adult:'Treine a escala de oitava no metrônomo, de 60 até 100, sempre limpa.'}},
agil3:{
 m:'Teclado ou violão (ou app de piano) e dois cartões: um sol (maior) e uma nuvem de chuva (menor).',
 ex:'Acorde maior soa alegre (sol), acorde menor soa mais sério ou triste (chuva). O arpejo é cantar as notas do acorde uma de cada vez.',
 p:['Toque um acorde maior e um menor e pergunte qual parece "sol" e qual parece "chuva".','Cante 1-3-5 maior e depois menor, lentamente.','Mostre que a diferença está na 3ª (meio tom abaixo no menor).','Acelere os arpejos.','Faça no app.'],
 c:'Jogo dos cartões: você toca, a criança levanta o sol ou a nuvem.',
 a:'Ligue ao louvor: muitos hinos começam em maior e passam por um acorde menor em frases mais reflexivas. Ouvir isso ajuda na harmonia mais tarde.',
 e:[['Cantar a 3ª maior no arpejo menor','Cante só 1-3 maior e 1-3 menor alternando.'],['Errar o salto para o 8','Imagine a nota antes, como na aula de oitavas.']],
 al:{kid:'Peça para alguém tocar ou cantar um acorde e diga se é "sol" ou "chuva".',adult:'Cante arpejos maiores e menores devagar e depois no app.'}},
glo1:{
 m:'A letra com o melisma desenhado em três "ondas" e o espelho.',
 ex:'O "Glória" é como uma onda que desce em três degraus de seis notas e termina na praia (a nota final). A vogal "ó" é o barco: é o mesmo barco do começo ao fim.',
 p:['Desenhe no quadro três ondas descendo e a nota final.','Cante só a 1ª onda em "ó", bem lento.','Junte a 2ª e a 3ª onda.','Cante tudo nota por nota, no seu ritmo, mantendo a boca igual (espelho).','Faça no app.'],
 c:'A criança passa o dedo nas ondas desenhadas enquanto canta. Conte que é o canto dos anjos no Natal.',
 a:'Peça para não aspirar entre as notas e não mudar a vogal. Treinar em grupos de seis é o caminho mais rápido.',
 e:[['Aspirar entre as notas ("hó-hó-hó")','Cante em "u" contínuo e depois volte para "ó".'],['A vogal virando "ô" ou "u" no agudo','Use o espelho e mantenha a boca de "ó".']],
 al:{kid:'Desenhe as ondas do "Glória" num papel e passe o dedo enquanto canta.',adult:'Cante uma onda por vez e depois tudo, nota por nota no app.'}},
theory_belt:{
 m:'Um exemplo gravado de voz forte saudável e o espelho. Para a demonstração: uma mangueira de jardim ou a imagem dela.',
 ex:'Belting é a voz de quem chama alguém de longe com alegria, não com raiva. É como a mangueira com o dedo na ponta: o jato vai longe porque está bem direcionado, não porque a torneira está no máximo.',
 p:['Ouça um exemplo de voz forte saudável e outro de grito.','Mostre os ingredientes: apoio, twang (brilho) e vogal mais falada.','Fale "Ei, você!" chamando de longe, com alegria: é a base do belting.','Explique os limites: dor, ardência ou rouquidão significam parar.','Faça o quiz do app.'],
 c:'Com crianças não se treina belting. Explique que a voz forte vem com o tempo e que agora o importante é cantar com alegria e sem gritar.',
 a:'Deixe claro que o belting é usado com moderação, nos pontos altos do louvor. Na fase da muda vocal (jovens), evite.',
 e:[['Confundir belting com grito','Use a fala chamando alguém de longe como modelo.'],['Treinar belting sem aquecer','Nunca. Aquecimento completo antes.']],
 al:{kid:'Cante com alegria, mas sem gritar. Quando ficar mais velho, o professor ensina a voz forte.',adult:'Ouça louvores e identifique onde o cantor usa voz forte e onde volta ao suave.'}},
twang:{
 m:'Espelho e uma garrafa PET cortada ao meio (um "megafone" improvisado), opcional.',
 ex:'O twang é o brilho da voz, como a voz de pato ou a risada da bruxa dos desenhos. Ele faz a voz "cortar" o som da banda sem precisar de força, como um megafone.',
 p:['"Nhé" brilhante, como um bebê fazendo manha.','Risada de bruxa ("nhé-hé-hé"), leve e aguda.','Chamada "Ê, ô!" como quem chama alguém na rua.','"Aleluia" falado com twang e depois cantado.','Compare o som com e sem twang; se tiver o megafone de garrafa, mostre como o som se projeta.'],
 c:'Risada de bruxa e voz de pato fazem muito sucesso. Mantenha o volume médio e faça poucas repetições.',
 a:'Explique que o twang estreita a parte de cima da laringe e dá projeção sem exigir força. Adultos se surpreendem como a voz "aparece" mais.',
 e:[['Voz apertada ou estridente','Diminua o volume e boceje entre as repetições.'],['Voz muito nasal','Abra mais a boca e pense no som na frente do rosto, não no nariz.']],
 al:{kid:'Faça a risada de bruxa e a voz de pato 3 vezes, bem leve.',adult:'Fale "aleluia" com twang e depois cante, em volume médio, 5 vezes.'}},
belt:{
 m:'Um elástico ou faixa elástica e uma garrafinha de água.',
 ex:'Alternar forte e suave é como dirigir bem: acelerar e frear com suavidade, sem trancos. O elástico mostra a voz esticando e voltando.',
 p:['Aqueça com canudo e com os exercícios de twang.','Cante a frase suave e depois forte, esticando o elástico no forte.','Volte ao suave sem perder a qualidade.','Observe pescoço e ombros: se aparecer tensão, pare.','Faça no app.'],
 c:'Não é uma aula para crianças. Se fizerem, use o leão (forte, sem gritar) e o ratinho (suave).',
 a:'A voz forte é ferramenta para os pontos altos do louvor. A habilidade principal desta aula é voltar ao suave com controle.',
 e:[['Tensão no pescoço','Pare, boceje e diminua o volume.'],['Não conseguir voltar ao suave','Faça a messa di voce lenta antes.']],
 al:{kid:'Brinque de leão e ratinho, sem gritar.',adult:'Faça a aula no máximo 2 vezes por semana e sempre depois de aquecer.'}},
theory_interp:{
 m:'Bíblia, a letra de um hino impressa e lápis de cor (para marcar dinâmica).',
 ex:'Interpretar é contar uma história com a música. Leia a mesma frase ("Santo é o Senhor") como notícia de jornal e depois como oração: o sentido muda tudo.',
 p:['Leia uma frase de duas formas e pergunte qual tocou mais.','Explique: o texto primeiro, depois o fraseado e a dinâmica.','Marque na letra, com cores, onde cantar suave e onde cantar forte.','Converse sobre adoração: servir à mensagem, não se exibir.','Faça o quiz do app.'],
 c:'Peça para a criança contar o que a letra diz com as próprias palavras e desenhar a cena do hino.',
 a:'Peça para cada um escrever em uma frase o que o hino quer dizer. Isso guia todas as escolhas de dinâmica e respiração.',
 e:[['Cantar todas as frases iguais','Marque na letra o ponto alto e o ponto de descanso.'],['Exagerar para emocionar','A emoção vem do texto, não do enfeite.']],
 al:{kid:'Desenhe o que o hino conta.',adult:'Escolha um hino e escreva em uma frase o que ele significa para você.'}},
messa:{
 m:'Um elástico e uma lanterna de celular (opcional, para mostrar a luz aumentando e diminuindo).',
 ex:'Messa di voce é como o nascer e o pôr do sol numa nota: começa suave, cresce até o forte e volta ao suave. O elástico estica e volta devagar.',
 p:['Mostre com o elástico: estica devagar e volta devagar.','Cante uma nota suave, cresça até o forte e diminua, na mesma vogal.','Mantenha a afinação igual do começo ao fim.','Peça a mão na barriga: o crescendo vem do ar.','Faça no app.'],
 c:'Use a lanterna do celular: a luz aumenta e diminui junto com a voz. As crianças imitam com as mãos se abrindo e fechando.',
 a:'É o exercício clássico de controle. A parte difícil é o diminuendo: a voz tende a desafinar ou ficar soprosa.',
 e:[['Afinação subindo no forte','Pense na nota "por cima" e não empurre.'],['Voz soprosa no diminuendo','Mantenha o apoio ativo até o fim.']],
 al:{kid:'Abra e feche as mãos enquanto canta uma nota crescendo e diminuindo.',adult:'Faça 3 messe di voce por dia com um elástico na mão.'}},
interp:{
 m:'Letra impressa de "Preciosa Graça", lápis de cor e celular para gravar.',
 ex:'Preparar a interpretação é fazer um "mapa" da música: onde respirar, onde é o ponto alto e onde se canta suave, como um mapa de viagem.',
 p:['Ler a letra como oração.','Marcar com lápis as respirações (vírgulas).','Pintar o ponto alto de cada estrofe.','Fazer o plano de dinâmica com cores (azul suave, vermelho forte).','Gravar e ouvir.'],
 c:'Use lápis de cor na letra: azul para cantar suave, vermelho para cantar forte.',
 a:'O roteiro serve para qualquer hino. Peça para trazerem um hino da igreja e aplicar.',
 e:[['Plano bonito no papel e cantar igual de sempre','Grave e compare com o plano.'],['Pontos altos demais','Escolha um ponto alto por estrofe.']],
 al:{kid:'Pinte a letra de azul e vermelho e cante seguindo as cores.',adult:'Faça o mapa da música de um hino da sua igreja, grave e ouça.'}},
glo2:{
 m:'Metrônomo e a letra com as ondas desenhadas.',
 ex:'Agora o "Glória" é cantado no tempo, num fôlego só, como um surfista que pega a onda inteira.',
 p:['Revise o melisma nota por nota.','Com o metrônomo lento, cante em colcheias.','Respire bem antes e cante num fôlego só.','Faça no app.'],
 c:'A criança faz o surfista com o corpo enquanto canta.',
 a:'Leveza é tudo: voz pesada não corre. Respire bem antes.',
 e:[['Ar acabar no meio','Respire antes e use menos volume.'],['Atrasar','Treine com o metrônomo.']],
 al:{kid:'Cante o "Glória" fazendo o surfista.',adult:'Treine com o metrônomo, subindo a velocidade aos poucos.'}},
tad:{
 m:'Letra impressa com o ponto alto marcado e o app.',
 ex:'A melodia é como uma subida até o topo de um monte: a frase vai crescendo até "exaltamos" e depois desce para o descanso em "louvor".',
 p:['Leia a letra e marque o ponto alto.','Cante em "lu" e depois com a letra.','Conduza a frase até o ponto alto e resolva com suavidade.','Faça no app.'],
 c:'Os braços sobem até o ponto alto e descem devagar no "louvor".',
 a:'Pense a nota alta antes e cante leve. Aplique o mapa de interpretação.',
 e:[['Gritar no ponto alto','Pense leve e use voz mista.'],['Resolver sem suavidade','Diminua o volume no fim.']],
 al:{kid:'Suba os braços até a nota alta e desça devagar.',adult:'Cante com o app e grave para ouvir o ponto alto.'}},
exam4:{
 m:'App, fone, canudo para aquecer e lugar silencioso.',
 ex:'A prova do Avançado mostra agilidade, melisma e vibrato (ou nota longa reta e afinada).',
 p:['Aquecimento completo com canudo.','Revise as escalas rápidas e o melisma.','O aluno faz a prova sozinho.','Ouça a gravação e comente.'],
 c:'Comemore a conquista com a turma.',
 a:'Lembre que a nota reta e afinada também é aprovada.',
 e:[['Tentar a velocidade máxima','Velocidade com precisão.'],['Forçar o vibrato','Nota reta e afinada também passa.']],
 al:{kid:'Aqueça e faça o desafio da medalha do Nível 4!',adult:'Faça a prova depois de aquecer e envie a gravação.'}},

/* ================= NÍVEL 5 ================= */
theory_group:{
 m:'Copos de vidro com um pouco de água (para mostrar "som que se mistura") ou dois celulares tocando a mesma nota.',
 ex:'Cantar em grupo é como fazer um suco: as frutas se misturam e viram um sabor só. Ninguém quer achar um pedaço de laranja inteiro no suco: ninguém deve "aparecer" sozinho no grupo.',
 p:['Peça para 4 alunos cantarem a mesma nota, cada um do seu jeito, e depois tentando soar como um só.','Explique uníssono e mistura (blend).','Combine a mesma vogal e o mesmo corte de som.','Mostre o gesto do líder para entrar e cortar.','Faça o quiz do app.'],
 c:'Brincadeira do "robô": todos cantam uma nota e terminam juntos quando você fecha a mão.',
 a:'Ensine a ouvir os vizinhos mais do que a si mesmo. Quem ouve só a própria voz canta alto demais.',
 e:[['Uma voz se destacando','Peça para todos ouvirem o vizinho e diminuírem o volume.'],['Cortes diferentes no fim das frases','Combine o gesto de corte do líder.']],
 al:{kid:'Cante com alguém de casa a mesma nota e tentem terminar juntos.',adult:'Cante junto com uma gravação de coral e tente "sumir" dentro do som.'}},
hold_note:{
 m:'Fone de ouvido, o app e uma bengala ou cabo de vassoura (para mostrar "ficar firme").',
 ex:'Manter a sua nota contra outra voz é como ficar parado em pé num ônibus em movimento: o ônibus anda, mas você fica firme no lugar.',
 p:['Sustente uma nota enquanto você toca uma escala no teclado.','Peça para tapar um ouvido com a mão se precisar.','Faça no app com fone.'],
 c:'"Estátua no ônibus": a criança fica firme enquanto você canta uma melodia em volta dela.',
 a:'É o primeiro passo da harmonia. Tapar um ouvido ajuda no começo.',
 e:[['Seguir a melodia','Tape um ouvido e pense na sua nota.'],['Desafinar quando a melodia passa perto','Mantenha a nota "por dentro".']],
 al:{kid:'Cante uma nota firme enquanto alguém de casa canta outra coisa.',adult:'Com fone, faça a aula até 60 ou mais.'}},
voz2a:{
 m:'Fone, o app e a letra com duas cores (melodia em cinza e 2ª voz colorida, como no app).',
 ex:'A 2ª voz caminha ao lado da melodia como um amigo de mãos dadas, sempre um passo abaixo.',
 p:['Cante só a 2ª voz, sem melodia.','Cante com a melodia tocando baixinho.','Aumente o volume da melodia aos poucos.','Faça no app com fone.'],
 c:'Divida a turma: metade melodia, metade 2ª voz.',
 a:'Aprenda primeiro a sua linha sozinho, depois junto.',
 e:[['Ir para a melodia','Cante a sua linha sozinho mais vezes.'],['Volume alto demais','A 2ª voz fica abaixo da melodia.']],
 al:{kid:'Cante a segunda voz junto com alguém que canta a melodia.',adult:'Com fone, faça a aula até 60 ou mais.'}},
unison:{
 m:'Fone de ouvido, o app e duas folhas de papel iguais (para a demonstração).',
 ex:'Uníssono é encaixar a sua voz na do grupo como colocar uma folha de papel exatamente em cima da outra: contra a luz, parece uma folha só.',
 p:['Faça a demonstração das folhas: tortas, aparecem duas; alinhadas, parece uma só.','Cante a Doxologia em grupo e peça para cada um ouvir o vizinho.','Combine a mesma vogal em cada sílaba longa ("Deus", "Pai") e o mesmo corte.','Explique por que usar fone no app: o microfone escuta só a sua voz.','Faça no app com fone.'],
 c:'"Cantar igualzinho, como um espelho": você canta uma frase e as crianças imitam até "sumir" dentro da sua voz.',
 a:'Ensine a ouvir mais o grupo do que a si mesmo. Uma boa dica é cantar com um ouvido parcialmente tapado pela mão para ouvir o próprio som sem exagerar o volume.',
 e:[['Cantar mais alto que o grupo','Diminua até ouvir os vizinhos com clareza.'],['Adiantar ou atrasar','Siga o líder e o pulso, não a sua pressa.']],
 al:{kid:'Cante junto com o app como um espelho, igualzinho.',adult:'Com fone, cante no app até 60 ou mais, tentando "sumir" dentro da melodia.'}},
theory_harm:{
 m:'Teclado (ou app de piano), papel e duas cores de lápis, e duas pessoas para a brincadeira da sombra.',
 ex:'A 2ª voz é como a sombra de quem anda na calçada: acompanha cada passo, sempre na mesma distância (uma terça abaixo). A 3ª voz é como um balão amarrado acima da cabeça.',
 p:['Toque e cante a melodia de "Cristo me ama".','Toque a melodia junto com a terça abaixo e peça para ouvirem as duas.','Desenhe as duas linhas no papel com cores diferentes: elas andam juntas.','Explique a 3ª voz (terça acima) e as sextas.','Faça o quiz do app.'],
 c:'Brincadeira da sombra: uma criança anda pela sala e outra imita ao lado, um pouquinho atrás. Depois cantam: uma a melodia, outra a "sombra".',
 a:'Mostre que a 2ª voz em terças é a mais usada nos ministérios e que o caminho é sempre aprender a própria linha sozinho antes de cantar junto.',
 e:[['Ir para a melodia sem perceber','Aprenda a sua linha sozinho e depois tape um ouvido ao cantar junto.'],['Achar que é só "cantar mais grave"','Mostre que a 2ª voz tem desenho próprio, nem sempre paralelo.']],
 al:{kid:'Brinque de sombra com alguém de casa, andando e depois cantando.',adult:'Toque uma melodia simples num app de piano e cante a terça abaixo, nota por nota.'}},
voz2b:{
 m:'Fone, o app e a letra de "Jubilosos te adoramos" com os finais de frase destacados.',
 ex:'No fim das frases a 2ª voz desce abaixo do tom (Si e Lá graves), como quem desce um degrau a mais da escada para chegar ao porão. É ali que a maioria escorrega.',
 p:['Cante a 2ª voz inteira sozinho, em "lu".','Treine só os finais de frase, onde ela desce ao Si e ao Lá graves.','Cante com a melodia tocando baixinho e depois mais alto.','Divida a turma em duas vozes e troquem.','Faça no app com fone.'],
 c:'Divida as crianças em dois times, um com a melodia e outro com a 2ª voz, e troquem os times na segunda vez.',
 a:'Os graves do fim pedem apoio e postura (lembre da aula de graves). Não abaixe o queixo para alcançar.',
 e:[['Perder a nota grave no fim da frase','Mais apoio e queixo paralelo ao chão.'],['Pular para a melodia no meio','Tape um ouvido e cante a sua linha mais vezes sozinho.']],
 al:{kid:'Cante a segunda voz com alguém de casa que canta a melodia.',adult:'Treine os finais de frase separados e depois faça a aula até 60 ou mais.'}},
voz3:{
 m:'Fone, o app e um enfeite qualquer (laço, flor) para a imagem da "cereja do bolo".',
 ex:'A 3ª voz fica uma terça acima da melodia. É a cereja do bolo: pequena, bonita e nunca maior que o bolo.',
 p:['Cante a 3ª voz sozinho, leve.','Cante com a melodia, com volume abaixo dela.','Peça para um grupo cantar a melodia e outro a 3ª voz.','Faça no app com fone.'],
 c:'Diga que a voz de cima é a "cereja do bolo": delicada e suave, para não "esconder" a melodia.',
 a:'A voz de cima chama atenção facilmente. Mantenha o volume abaixo da melodia e use voz leve (mista ou de cabeça).',
 e:[['Volume alto, roubando a atenção','Diminua até ouvir bem a melodia.'],['Ir para a melodia','Tape um ouvido e pense na sua linha.']],
 al:{kid:'Cante a voz de cima bem suave, como a cereja do bolo.',adult:'Faça a aula até 60 ou mais, sempre com volume abaixo da melodia.'}},
tad_v2:{
 m:'Fone, o app e a letra de "Te adoramos" com o ponto alto marcado.',
 ex:'No ponto alto, a melodia vai ao Dó agudo e a 2ª voz para no Lá: é como duas pessoas subindo um monte, uma vai até o topo e a outra fica um pouco abaixo, sustentando.',
 p:['Cante a 2ª voz sozinho.','Treine o ponto alto separado (Lá da 2ª voz contra o Dó da melodia).','Cante com a melodia.','Faça no app com fone.'],
 c:'Divida a turma em duas vozes. No ponto alto, os dois grupos levantam os braços, mas a 2ª voz para "no ombro" e a melodia vai "até a cabeça".',
 a:'No ponto alto, a tendência é acompanhar a melodia até o Dó. Treine a chegada no Lá várias vezes.',
 e:[['Seguir a melodia no ponto alto','Treine separado e pense no Lá antes.'],['Volume maior que a melodia','A 2ª voz sustenta, não lidera.']],
 al:{kid:'Cante a segunda voz com alguém de casa cantando a melodia.',adult:'Treine o ponto alto separado e depois faça a aula até 60 ou mais.'}},
theory_band:{
 m:'Um violão ou teclado (se tiver) e uma cifra impressa com a introdução marcada.',
 ex:'Cantar com a banda é como entrar num carro em movimento: você precisa saber o tom (para onde vai), a contagem (quando pular) e o pulso (a velocidade).',
 p:['Toque o acorde do tom e peça para acharem a primeira nota.','Toque uma introdução e conte em voz alta "1, 2, 3, 4" para a entrada.','Bata o pulso com a banda (ou o violão).','Ensine os sinais combinados: repetir, subir tom, finalizar.','Faça o quiz do app.'],
 c:'Faça um "ensaio de banda" com instrumentos de brinquedo ou de garrafa e arroz. A criança aprende a esperar a introdução e entrar na contagem.',
 a:'Ensine a perguntar à banda o tom e a primeira nota antes do ensaio, e a combinar os sinais (mão para cima = subir tom, mão girando = repetir).',
 e:[['Entrar antes da hora','Conte a introdução em voz baixa.'],['Começar em outro tom','Peça o acorde e cante a primeira nota baixinho antes.']],
 al:{kid:'Brinque de banda em casa: alguém toca um chocalho e você só começa a cantar depois de contar até 4.',adult:'Pegue a cifra de um louvor da igreja e descubra o tom e a primeira nota.'}},
chordstart:{
 m:'Teclado, violão ou o app, e três cartões numerados: 1 (fundamental), 3 (terça) e 5 (quinta).',
 ex:'O acorde é como uma família de três pessoas: o pai (fundamental), a mãe (terça) e o filho (quinta). Muitos louvores começam na mãe ou no filho, não no pai.',
 p:['Toque o acorde e cante a fundamental, a terça, a quinta e a fundamental de novo (1-3-5-1).','Mostre um cartão e a turma canta aquela nota do acorde.','Pegue um louvor da igreja que começa na terça ou na quinta e ache a primeira nota.','Faça no app, cantando o nome das notas.'],
 c:'Use a família: "agora cantem a nota do pai, agora da mãe, agora do filho". As crianças adoram.',
 a:'É a habilidade mais útil no ministério: o teclado dá o acorde e você acha a sua nota sozinho. Treine com os louvores do repertório da igreja.',
 e:[['Cantar sempre a fundamental','Cante 1-3-5 até achar a nota do louvor.'],['Desafinar a terça','Toque 1 e 3 juntos e ouça o "encaixe".']],
 al:{kid:'Brinque com alguém de casa: a pessoa diz "pai", "mãe" ou "filho" e você canta a nota.',adult:'Escolha 3 louvores da igreja e descubra se começam na fundamental, na terça ou na quinta.'}},
theory_mic:{
 m:'Um microfone (ou escova de cabelo, garrafinha ou controle remoto) e uma régua.',
 ex:'O microfone é como uma lupa para o som: perto aumenta, longe diminui. Saber a distância é como saber segurar uma lupa.',
 p:['Mostre a distância base: dois a quatro dedos da boca.','Mostre o ângulo: o microfone aponta para a boca, não para o queixo.','Explique o "braço": afasta no forte e aproxima no suave.','Explique as plosivas (P e B) e como desviar.','Faça o quiz do app.'],
 c:'Cada criança usa uma escova de cabelo como microfone. "Dois dedinhos da boca" é a regra.',
 a:'Explique como ajudar o técnico de som: passar o som com a voz real do culto, não mais baixa nem mais alta.',
 e:[['Microfone longe demais ou abaixado','Dois a quatro dedos, apontado para a boca.'],['Estouros no P e no B','Ângulo leve, de lado.']],
 al:{kid:'Use uma escova de cabelo como microfone, a dois dedinhos da boca.',adult:'Treine com qualquer objeto parecido com microfone, medindo a distância com os dedos.'}},
mic_tech:{
 m:'Microfone real ou objeto parecido (escova, garrafinha), espelho e celular para gravar.',
 ex:'O braço é o "botão de volume" do microfone: no forte o microfone se afasta, no suave se aproxima, para o som chegar sempre igual à igreja.',
 p:['Posição base: dois a quatro dedos da boca, cotovelo relaxado.','Frase suave com o microfone perto.','Frase forte afastando o microfone.','Palavras com P e B virando o microfone levemente de lado.','Grave com o celular e assista.'],
 c:'Escova de cabelo como microfone e a brincadeira do "elevador do microfone": no forte ele "sobe" (afasta), no suave "desce" (aproxima).',
 a:'Grave com o celular para ver o movimento do braço. O objetivo é automatizar, para no culto não precisar pensar nisso.',
 e:[['Esquecer de afastar no forte','Exagere o movimento no treino.'],['Segurar pela cabeça do microfone (a grade)','Segure no corpo do microfone.']],
 al:{kid:'Cante com a escova de cabelo, afastando no forte e aproximando no suave.',adult:'Grave-se cantando um louvor com um objeto como microfone e observe o braço.'}},
theory_presence:{
 m:'Bíblia e espelho.',
 ex:'O ministro de louvor é como um guia de caminhada: ele não caminha sozinho na frente, ele leva o grupo junto. Presença é conduzir as pessoas a Deus, não a si mesmo.',
 p:['Leia um texto sobre adoração (por exemplo, Salmo 100).','Converse sobre preparo espiritual antes de cantar.','Mostre postura e olhar: olhar a congregação e não o chão.','Fale sobre humildade e imprevistos (microfone falha, erro de letra).','Faça o quiz do app.'],
 c:'Explique que, quando cantamos na igreja, ajudamos todos a louvar a Deus. Pergunte: "Como você mostra no rosto que está feliz em louvar?"',
 a:'Converse sobre a diferença entre apresentação e ministração. Combine o que fazer em imprevistos: seguir cantando com calma.',
 e:[['Olhos fechados o tempo todo','Alterne olhar a congregação e momentos de adoração.'],['Nervosismo travando o corpo','Respire antes e ore.']],
 al:{kid:'Cante um louvor na frente do espelho, com um sorriso no rosto.',adult:'Leia o Salmo 100 e escreva como ele muda a sua forma de ministrar.'}},
presence:{
 m:'Espelho ou celular para gravar em vídeo.',
 ex:'Treinar a presença é como treinar as notas: a gente se vê, percebe o que melhorar e repete.',
 p:['Preparo: oração curta e respiração.','Entrada: andar até o lugar, olhar a congregação e sorrir.','Cantar um louvor decorado olhando para frente.','Assistir o vídeo e anotar um ponto forte e um ponto a melhorar.'],
 c:'Faça um "mini culto": cada criança canta uma frase para a turma, olhando para todos.',
 a:'Assistir a si mesmo é desconfortável, mas é a forma mais rápida de melhorar. Combine de olhar com carinho e não com crítica.',
 e:[['Ficar preso na letra','Decore a letra antes.'],['Corpo travado','Respire e solte os ombros.']],
 al:{kid:'Cante um louvor para a sua família, olhando para todos.',adult:'Grave um vídeo cantando e anote um ponto forte e um a melhorar.'}},
prep:{
 m:'Letra impressa, cifra, lápis de cor e celular para gravar.',
 ex:'Preparar um louvor para o culto é como preparar uma refeição para visitas: você escolhe os ingredientes (tom e arranjo), prepara antes (ensaio) e serve com carinho (ministração).',
 p:['Estudo do texto e da estrutura (estrofe, refrão, ponte).','Escolha do tom que a congregação consegue cantar.','Arranjo e vozes: quem canta o quê.','Ensaio com a banda e gravação.'],
 c:'Monte com as crianças a "receita do louvor": um papel com cada passo desenhado.',
 a:'Use o roteiro com qualquer louvor do repertório. A escolha do tom é pensando na congregação, não no solista.',
 e:[['Tom bom para o cantor e ruim para a igreja','Teste o tom cantando com pessoas comuns.'],['Ensaiar só no dia','Ensaie durante a semana.']],
 al:{kid:'Faça a "receita do louvor" desenhando cada passo.',adult:'Aplique o roteiro num louvor que você vai cantar na igreja.'}},
final_song:{
 m:'Fone, o app e a letra completa de "Preciosa Graça" com o mapa de interpretação.',
 ex:'É o "culto de verdade": tudo o que foi aprendido junto, do começo ao fim, sem parar.',
 p:['Aquecimento completo.','Revise o mapa de interpretação.','Cante do início ao fim com o app.','Grave e ouça.'],
 c:'Faça uma pequena apresentação para as famílias.',
 a:'Aplique tudo: postura, apoio, afinação, ritmo, interpretação e presença.',
 e:[['Parar ao errar','Continue cantando, como no culto.'],['Cansar no fim','Respire nos lugares marcados.']],
 al:{kid:'Cante o louvor inteiro para a sua família.',adult:'Com fone, cante no app e grave para ouvir.'}},
exam5:{
 m:'App, fone e lugar silencioso.',
 ex:'A prova final mostra que o aluno está pronto para servir no ministério: acha a nota pelo acorde, mantém a 2ª voz e canta um louvor completo.',
 p:['Aquecimento completo.','Revise o acorde, a 2ª voz e o louvor.','O aluno faz a prova sozinho.','Ouça a gravação e comente.'],
 c:'Faça uma formatura com certificado feito à mão.',
 a:'Comemore a conquista e combine os próximos passos no ministério.',
 e:[['Nervosismo','Respire e ore antes.'],['Esquecer de aquecer','Aquecimento é parte da prova.']],
 al:{kid:'Aqueça e faça o desafio da medalha final!',adult:'Faça a prova depois de aquecer e envie a gravação.'}}
};
